// 定义一个联合类型，可以是字符串、数字或布尔值
type Primitive = string | number | boolean;

function processValue(value: Primitive): string {
  // 使用 typeof 类型守卫缩小类型
  if (typeof value === "string") {
    // 这里 value 被窄化为 string
    return `String: ${value.toUpperCase()}`;
  } else if (typeof value === "number") {
    // 窄化为 number
    return `Number: ${value.toFixed(2)}`;
  } else {
    // 此时只剩下 boolean
    return `Boolean: ${value ? "yes" : "no"}`;
  }
}

// 测试
console.log(processValue("hello"));   // String: HELLO
console.log(processValue(42));        // Number: 42.00
console.log(processValue(true));      // Boolean: yes

